import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, SphereGeometry, IcosahedronGeometry, InstancedMesh } from 'three/webgpu';
import { mix, uv, color } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, AmbientLight, DirectionalLight, Matrix4, Vector3, Color } = ctx.THREE;

  // Root group (position/rotation/scale applied by adapter)
  const root = new Group();

  // ---------- Backdrop Gradient Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  // vertical gradient from #0b0b10 (top) to #16161d (bottom)
  backdropMat.colorNode = mix(color('#0b0b10'), color('#16161d'), uv().y);
  backdropMat.transparent = true;
  backdropMat.depthWrite = false;
  const backdrop = new ctx.THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- Core Accent Sphere ----------
  const coreGeom = new SphereGeometry(0.5, 32, 32);
  const coreMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 1,
    transparent: true,
    blending: ctx.THREE.AdditiveBlending,
    depthWrite: false,
  });
  const coreSphere = new ctx.THREE.Mesh(coreGeom, coreMat);
  coreSphere.position.set(0, 0, 0);
  root.add(coreSphere);

  // ---------- Instanced Particle Field ----------
  const particleCount = 1200;
  const particleGeom = new IcosahedronGeometry(0.012, 0);
  const particleMat = new MeshStandardNodeMaterial({
    color: '#e8ecf2',
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0.9,
  });
  const particles = new InstancedMesh(particleGeom, particleMat, particleCount);
  const dummyMatrix = new Matrix4();
  const dummyPos = new Vector3();
  const coreCenter = new Vector3(0, 0, -1.5);
  const radii = new Vector3(3, 2, 2.5); // half extents of 6x4x5 ellipsoid
  for (let i = 0; i < particleCount; i++) {
    // Random point on ellipsoidal shell
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const x = radii.x * Math.sin(phi) * Math.cos(theta);
    const y = radii.y * Math.sin(phi) * Math.sin(theta);
    const z = radii.z * Math.cos(phi);
    dummyPos.set(x, y, z).add(coreCenter);
    // start at core with scale 0 (primitive will animate)
    dummyMatrix.compose(dummyPos, new ctx.THREE.Quaternion(), new Vector3(0, 0, 0));
    particles.setMatrixAt(i, dummyMatrix);
  }
  particles.instanceMatrix.needsUpdate = true;
  root.add(particles);

  // ---------- Text Elements ----------
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 124,
      color: config.intent?.visualSpec?.colors?.ink ?? '#16161d',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text, opts);
    // Position based on role
    if (item.role === 'hero') {
      txt.position.set(0, 0.5, 0.5);
    } else if (item.role === 'subhead') {
      txt.position.set(0, -0.25, 0.5);
    } else if (item.role === 'caption') {
      txt.position.set(0, -2.25, 0.5);
    }
    root.add(txt);
  }

  // ---------- Lighting ----------
  const ambient = new AmbientLight(0xffffff, 0.6);
  root.add(ambient);
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(5, 5, 5);
  root.add(keyLight);
  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-5, -5, -5);
  root.add(rimLight);

  // ---------- Cinematic Primitives ----------
  const activePrimitives = [];
  const primitivesConfig = config.cinematicPrimitives || [];
  for (const prim of primitivesConfig) {
    const instance = ctx.primitives[prim.name](root, prim.params);
    activePrimitives.push(instance);
  }

  // ---------- GSAP Timelines ----------
  const timelines = [];

  // Core pulse (emissive intensity sine wave at 0.1 Hz)
  const pulseTl = gsap.to(coreMat, {
    emissiveIntensity: 1.5,
    duration: 5,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut',
  });
  timelines.push(pulseTl);

  // Attach handlers container (none defined in spec)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = function () {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();
    particleGeom.dispose();
    particleMat.dispose();

    // Dispose instanced mesh
    particles.geometry.dispose();
    particles.material.dispose();

    // Kill GSAP timelines
    for (const tl of timelines) tl.kill();

    // Cleanup primitives
    for (const p of activePrimitives) p.cleanup && p.cleanup();

    // Remove from parent if still attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
